886: Guint XRef::strToUnsigned(char *s) {
887:   Guint x;
888:   char *p;
889:   int i;
890: 
891:   x = 0;
892:   for (p = s, i = 0; *p && isdigit(*p) && i < 10; ++p, ++i) {
893:     x = 10 * x + (*p - '0');
894:   }
895:   return x;
896: }

