143: Stream *Parser::makeStream(Object *dict, Guchar *fileKey,
144: 			   CryptAlgorithm encAlgorithm, int keyLength,
145: 			   int objNum, int objGen) {
146:   Object obj;
147:   BaseStream *baseStr;
148:   Stream *str;
149:   Guint pos, endPos, length;
150: 
151:   // get stream start position
152:   lexer->skipToNextLine();
153:   pos = lexer->getPos();
154: 
155:   // get length
156:   dict->dictLookup("Length", &obj);
157:   if (obj.isInt()) {
158:     length = (Guint)obj.getInt();
159:     obj.free();
160:   } else {
161:     error(getPos(), "Bad 'Length' attribute in stream");
162:     obj.free();
163:     return NULL;
164:   }
165: 
166:   // check for length in damaged file
167:   if (xref && xref->getStreamEnd(pos, &endPos)) {
168:     length = endPos - pos;
169:   }
170: 
171:   // in badly damaged PDF files, we can run off the end of the input
172:   // stream immediately after the "stream" token
173:   if (!lexer->getStream()) {
174:     return NULL;
175:   }
176:   baseStr = lexer->getStream()->getBaseStream();
177: 
178:   // skip over stream data
179:   lexer->setPos(pos + length);
180: 
181:   // refill token buffers and check for 'endstream'
182:   shift();  // kill '>>'
183:   shift();  // kill 'stream'
184:   if (buf1.isCmd("endstream")) {
185:     shift();
186:   } else {
187:     error(getPos(), "Missing 'endstream'");
188:     // kludge for broken PDF files: just add 5k to the length, and
189:     // hope its enough
190:     length += 5000;
191:   }
192: 
193:   // make base stream
194:   str = baseStr->makeSubStream(pos, gTrue, length, dict);
195: 
196:   // handle decryption
197:   if (fileKey) {
198:     str = new DecryptStream(str, fileKey, encAlgorithm, keyLength,
199: 			    objNum, objGen);
200:   }
201: 
202:   // get filters
203:   str = str->addFilters(dict);
204: 
205:   return str;
206: }
