208: void Parser::shift() {
209:   if (inlineImg > 0) {
210:     if (inlineImg < 2) {
211:       ++inlineImg;
212:     } else {
213:       // in a damaged content stream, if 'ID' shows up in the middle
214:       // of a dictionary, we need to reset
215:       inlineImg = 0;
216:     }
217:   } else if (buf2.isCmd("ID")) {
218:     lexer->skipChar();		// skip char after 'ID' command
219:     inlineImg = 1;
220:   }
221:   buf1.free();
222:   buf1 = buf2;
223:   if (inlineImg > 0)		// don't buffer inline image data
224:     buf2.initNull();
225:   else
226:     lexer->getObj(&buf2);
227: }

