453: GBool StreamPredictor::getNextLine() {
454:   int curPred;
455:   Guchar upLeftBuf[gfxColorMaxComps * 2 + 1];
456:   int left, up, upLeft, p, pa, pb, pc;
457:   int c;
458:   Gulong inBuf, outBuf, bitMask;
459:   int inBits, outBits;
460:   int i, j, k, kk;
461: 
462:   // get PNG optimum predictor number
463:   if (predictor >= 10) {
464:     if ((curPred = str->getRawChar()) == EOF) {
465:       return gFalse;
466:     }
467:     curPred += 10;
468:   } else {
469:     curPred = predictor;
470:   }
471: 
472:   // read the raw line, apply PNG (byte) predictor
473:   memset(upLeftBuf, 0, pixBytes + 1);
474:   for (i = pixBytes; i < rowBytes; ++i) {
475:     for (j = pixBytes; j > 0; --j) {
476:       upLeftBuf[j] = upLeftBuf[j-1];
477:     }
478:     upLeftBuf[0] = predLine[i];
479:     if ((c = str->getRawChar()) == EOF) {
480:       if (i > pixBytes) {
481: 	// this ought to return false, but some (broken) PDF files
482: 	// contain truncated image data, and Adobe apparently reads the
483: 	// last partial line
484: 	break;
485:       }
486:       return gFalse;
487:     }
488:     switch (curPred) {
489:     case 11:			// PNG sub
490:       predLine[i] = predLine[i - pixBytes] + (Guchar)c;
491:       break;
492:     case 12:			// PNG up
493:       predLine[i] = predLine[i] + (Guchar)c;
494:       break;
495:     case 13:			// PNG average
496:       predLine[i] = ((predLine[i - pixBytes] + predLine[i]) >> 1) +
497: 	            (Guchar)c;
498:       break;
499:     case 14:			// PNG Paeth
500:       left = predLine[i - pixBytes];
501:       up = predLine[i];
502:       upLeft = upLeftBuf[pixBytes];
503:       p = left + up - upLeft;
504:       if ((pa = p - left) < 0)
505: 	pa = -pa;
506:       if ((pb = p - up) < 0)
507: 	pb = -pb;
508:       if ((pc = p - upLeft) < 0)
509: 	pc = -pc;
510:       if (pa <= pb && pa <= pc)
511: 	predLine[i] = left + (Guchar)c;
512:       else if (pb <= pc)
513: 	predLine[i] = up + (Guchar)c;
514:       else
515: 	predLine[i] = upLeft + (Guchar)c;
516:       break;
517:     case 10:			// PNG none
518:     default:			// no predictor or TIFF predictor
519:       predLine[i] = (Guchar)c;
520:       break;
521:     }
522:   }
523: 
524:   // apply TIFF (component) predictor
525:   if (predictor == 2) {
526:     if (nBits == 1) {
527:       inBuf = predLine[pixBytes - 1];
528:       for (i = pixBytes; i < rowBytes; i += 8) {
529: 	// 1-bit add is just xor
530: 	inBuf = (inBuf << 8) | predLine[i];
531: 	predLine[i] ^= inBuf >> nComps;
532:       }
533:     } else if (nBits == 8) {
534:       for (i = pixBytes; i < rowBytes; ++i) {
535: 	predLine[i] += predLine[i - nComps];
536:       }
537:     } else {
538:       memset(upLeftBuf, 0, nComps + 1);
539:       bitMask = (1 << nBits) - 1;
540:       inBuf = outBuf = 0;
541:       inBits = outBits = 0;
542:       j = k = pixBytes;
543:       for (i = 0; i < width; ++i) {
544: 	for (kk = 0; kk < nComps; ++kk) {
545: 	  if (inBits < nBits) {
546: 	    inBuf = (inBuf << 8) | (predLine[j++] & 0xff);
547: 	    inBits += 8;
548: 	  }
549: 	  upLeftBuf[kk] = (Guchar)((upLeftBuf[kk] +
550: 				    (inBuf >> (inBits - nBits))) & bitMask);
551: 	  inBits -= nBits;
552: 	  outBuf = (outBuf << nBits) | upLeftBuf[kk];
553: 	  outBits += nBits;
554: 	  if (outBits >= 8) {
555: 	    predLine[k++] = (Guchar)(outBuf >> (outBits - 8));
556: 	    outBits -= 8;
557: 	  }
558: 	}
559:       }
560:       if (outBits > 0) {
561: 	predLine[k++] = (Guchar)((outBuf << (8 - outBits)) +
562: 				 (inBuf & ((1 << (8 - outBits)) - 1)));
563:       }
564:     }
565:   }
566: 
567:   // reset to start of line
568:   predIdx = pixBytes;
569: 
570:   return gTrue;
571: }
